    skEllipse(s, "e1", { "center" : vector(0, 0) * millimeter, "majorRadius" : 10 * millimeter, "minorRadius" : 5 * millimeter });
    skCircle(s, "c2", { "center" : vector(14, 4) * millimeter, "radius" : 3 * millimeter });
    skConstraint(s, "fix_e1", { "constraintType" : ConstraintType.FIX, "localFirst" : "e1" });
    skConstraint(s, "c", { "constraintType" : ConstraintType.TANGENT, "localFirst" : "e1", "localSecond" : "c2" });
    skSolve(s);
    return sketchProbe(context, id + "s");
}

